const LANGUAGE_CHANGE_TEXT: Record<RequesterLanguage, string> = {
  English: "Changing language...",
  Afrikaans: "Taal word verander...",
  isiZulu: "Ulimi luyashintshwa...",
  isiXhosa: "Ulwimi luyatshintshwa...",
  Sesotho: "Puo e a fetolwa...",
  Setswana: "Puo e a fetolwa...",
  Sepedi: "Leleme le a fetolwa...",
  siSwati: "Lulwimi luyashintjwa...",
  Tshivenda: "Luambo lu khou shandukiswa...",
  isiNdebele: "Ilimi liyatjhugululwa...",
  XiTsonga: "Ririmi ra cinca...",
};

export function requesterText(language: RequesterLanguage, text: string, values?: Record<string, string | number>) {
  const etaMessage = text.match(/^A responder has been assigned\. Estimated arrival: (\d+) minutes?\.?$/i);
  const changedStatusMessage = text.match(/^The emergency request status has changed to (.+?)\.?$/i);
  const cancelledRequestMessage = text.match(/^Your request (.+?) has been successfully cancelled\.?$/i);
  // API values such as `medical` and `assigned` are often lowercase, while the
  // translation keys are the labels shown in the UI. Resolve those labels without
  // changing arbitrary user-entered text or address values.
  const titleCaseLabel = text.replace(/\b[a-z]/g, (letter) => letter.toUpperCase());
  const lowerCaseLabel = text.toLowerCase();
  const lookup = (key: string) => REQUESTER_PAGE_TRANSLATION_OVERRIDES[language]?.[key]
    ?? REQUESTER_NOTIFICATION_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_MAP_STATUS_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_OPERATION_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_PAGE_CORE_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_REQUEST_FORM_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_EMERGENCY_CATEGORY_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_DESCRIPTION_PROMPT_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_FORM_PLACEHOLDER_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_PRIORITY_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_CANCEL_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_AI_SHEET_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_AI_DIALOG_EXTENDED_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_TRACK_UI_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_FORM_TRACK_TRANSLATIONS[language]?.[key]
    ?? AI_LAUNCHER_TRANSLATIONS[language]?.[key]
    ?? AI_COMPOSER_TRANSLATIONS[language]?.[key]
    ?? BLIND_HOME_VOICE_TRANSLATIONS[language]?.[key]
    ?? PROFILE_SECTION_TRANSLATIONS[language]?.[key]
    ?? PROFILE_EDIT_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_PROFILE_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_PROFILE_LABEL_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_ROLE_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_SETTINGS_TRANSLATIONS[language]?.[key]
    ?? REQUESTER_PAGE_TRANSLATIONS[language]?.[key]
    ?? INTAKE_TRANSLATIONS[language]?.[key];
  const interpolate = (template: string, replacements?: Record<string, string | number>) => {
    let result = template;
    for (const [key, value] of Object.entries(replacements ?? {})) result = result.replaceAll(`{${key}}`, String(value));
    return result;
  };

  if (etaMessage) {
    const template = "A responder has been assigned. Estimated arrival: {eta} minutes.";
    return interpolate(lookup(template) ?? template, { ...values, eta: etaMessage[1] });
  }
  if (changedStatusMessage && changedStatusMessage[1] !== "{status}") {
    const rawStatus = changedStatusMessage[1].trim().replace(/[.!?]+$/, "").replace(/_/g, " ");
    const statusTitleCase = rawStatus.replace(/\b[a-z]/g, (letter) => letter.toUpperCase());
    const status = lookup(rawStatus) ?? lookup(statusTitleCase) ?? lookup(rawStatus.toLowerCase()) ?? rawStatus;
    const template = "The emergency request status has changed to {status}.";
    return interpolate(lookup(template) ?? template, { ...values, status });
  }
  if (cancelledRequestMessage && cancelledRequestMessage[1] !== "{reference}") {
    const template = "Your request {reference} has been successfully cancelled.";
    return interpolate(lookup(template) ?? template, { ...values, reference: cancelledRequestMessage[1] });
  }

  let result = text === "Changing language..."
    ? LANGUAGE_CHANGE_TEXT[language]
    : language === "isiZulu"
    ? (ZULU_TEXT[text] ?? ZULU_TEXT[titleCaseLabel] ?? lookup(text) ?? lookup(titleCaseLabel) ?? lookup(lowerCaseLabel) ?? text)
    : (lookup(text) ?? lookup(titleCaseLabel) ?? lookup(lowerCaseLabel) ?? text);
  for (const [key, value] of Object.entries(values ?? {})) result = result.replaceAll(`{${key}}`, String(value));
  return result;
}

export function requesterLocale(language: RequesterLanguage) {
  const locale: Record<RequesterLanguage, string> = {
    English: "en-ZA", Afrikaans: "af-ZA", isiZulu: "zu-ZA", isiXhosa: "xh-ZA",
    Sesotho: "st-ZA", Setswana: "tn-ZA", Sepedi: "nso-ZA", siSwati: "ss-SZ",
    Tshivenda: "ve-ZA", isiNdebele: "nr-ZA", XiTsonga: "ts-ZA",
  };
  return locale[language];
}

export function requesterTimeAgo(value: string, language: RequesterLanguage) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return requesterText(language, "Date unavailable");
  const seconds = Math.round((date.getTime() - Date.now()) / 1000);
  const absoluteSeconds = Math.abs(seconds);
  const unit: Intl.RelativeTimeFormatUnit = absoluteSeconds < 60
    ? "second"
    : absoluteSeconds < 3600
      ? "minute"
      : absoluteSeconds < 86400
        ? "hour"
        : absoluteSeconds < 2_592_000
          ? "day"
          : absoluteSeconds < 31_536_000
            ? "month"
            : "year";
  const unitSeconds: Record<"second" | "minute" | "hour" | "day" | "month" | "year", number> = {
    second: 1,
    minute: 60,
    hour: 3600,
    day: 86400,
    month: 2_592_000,
    year: 31_536_000,
  };
  try {
    const formatter = new Intl.RelativeTimeFormat(requesterLocale(language), { numeric: "auto" });
    return formatter.format(Math.round(seconds / unitSeconds[unit]), unit);
  } catch {
    return new Intl.RelativeTimeFormat("en-ZA", { numeric: "auto" }).format(Math.round(seconds / unitSeconds[unit]), unit);
  }
}

export function useRequesterLanguage(userId: string): RequesterLanguage {
  const [language, setLanguage] = useState<RequesterLanguage>(() => userId ? readRequesterLanguage(userId) : "English");
  useEffect(() => {
    const languageTags: Record<RequesterLanguage, string> = { English: "en", Afrikaans: "af", isiZulu: "zu", isiXhosa: "xh", Sesotho: "st", Setswana: "tn", Sepedi: "nso", siSwati: "ss", Tshivenda: "ve", isiNdebele: "nr", XiTsonga: "ts" };
    const applyLanguage = (next: RequesterLanguage) => {
      setLanguage(next);
      document.documentElement.lang = languageTags[next];
    };
    if (!userId) { applyLanguage("English"); return; }
    applyLanguage(readRequesterLanguage(userId));
    const onChange = (event: Event) => {
      const detail = (event as CustomEvent<{ userId?: string; language?: RequesterLanguage }>).detail;
      if (detail?.userId === userId && detail.language) applyLanguage(detail.language);
    };
    window.addEventListener("live:language-changed", onChange);
    return () => window.removeEventListener("live:language-changed", onChange);
  }, [userId]);
  return language;
}
